input.command:
node -e '
const L=require("fs").readFileSync("design/gdd/emitter-state-and-light-exposure-query.md","utf8").split("\n");
const cnt=s=>s.replace(/`[^`]*`/g,m=>m.replace(/\|/g,"\0")).split("|").length-1;
let i=0,bad=0;
while(i<L.length){ if(L[i].startsWith("|")&&L[i+1]&&/^\|[\s:|-]+\|$/.test(L[i+1])){const h=cnt(L[i]);let j=i;while(j<L.length&&L[j].startsWith("|")){if(cnt(L[j])!==h){console.log("row",j+1,cnt(L[j]),h,L[j].slice(0,60));bad++}j++}i=j}else i++}
console.log("bad",bad);
// duplicate amendment markers
let d=0;L.forEach((l,n)=>{const m=l.match(/\*\(Amended 2026-10-29 — ADR-00\d\d sync[^)]*\)\*/g);if(m){const s=new Set();m.forEach(x=>{if(s.has(x)){}else s.add(x)});}});
'

